import numpy as np
from scipy.optimize import least_squares
t,x,v,a=df['t'].values,df['x'].values,df['v'].values,df['dv_dt'].values
fams={
 'cos(wt)*v, sin(wt)*x': lambda p: [np.cos(p[0]*t)*v, np.sin(p[0]*t)*x],
 'cos(wt)*x, sin(wt)*v': lambda p: [np.cos(p[0]*t)*x, np.sin(p[0]*t)*v],
 'cos(wt), v': lambda p: [np.cos(p[0]*t), v],
 'exp(-p t)*v, cos(wt)': lambda p: [np.exp(-p[1]*t)*v, np.cos(p[0]*t)],
 'cos(wt)*v^2, v': lambda p: [np.cos(p[0]*t)*v*v, v],
 'exp(-pt)*x, v': lambda p: [np.exp(-p[1]*t)*x, v],
}
for name,f in fams.items():
    bestr=None
    for w0 in [0.3,0.6,1.0,1.5]:
        for s0 in [0.1,0.5]:
            def resid(p):
                cols=[x**1.5,(x/(1+p[2]*x))*v]+f([p[0],p[1]] if len(p)>1 else [p[0]])
                M=np.column_stack(cols)
                c_=np.linalg.lstsq(M,a,rcond=None)[0]
                return a-M@c_
            try:
                r=least_squares(resid,[w0,s0,1.0],max_nfev=300)
                nm=np.mean(r.fun**2)/np.var(a)
                if bestr is None or nm<bestr[0]: bestr=(round(float(nm),6),np.round(r.x,4))
            except Exception as e: pass
    print(name,bestr)

